  if(result.state==='rejected'){forget();dirty=false;pendingNotice();const editorStatus=p.route==='campaigns'?'campaign-edit-status':'audience-edit-status';notice(el(editorStatus)?editorStatus:p.route==='campaigns'?'campaign-draft-status':'audience-draft-status','A origem recusou esta alteração. Reabra o registro atual antes de corrigir.','warning');return;}
