 function nativeNewDefinition(){const code='qa-native-'+scope.brand+'-'+nativeCreateKey.slice(0,8),domain=scope.brand==='aristo'?'oaristocrata.com':'fishermans.com.br';return {name:'[QA SAB17] Agenda nativa '+scope.brand+' '+nativeCreateKey.slice(0,8),subject:'QA Agenda nativa',initiative:{key:code,name:'QA Agenda nativa'},utm_campaign:code,from_email:'avisos@'+domain,reply_to:'contato@'+domain,list_ids:[nativeFrozen.list_id],template_id:catalog.templates.find(t=>t.available)?.id,text:'Conferência interna de agendamento. https://'+domain+'/collections/all {{ UnsubscribeURL }}',html:'<p>Conferência interna de agendamento. <a href="https://'+domain+'/collections/all">Loja</a> <a href="{{ UnsubscribeURL }}">Sair da lista</a></p>',tags:['qa-native17'],send_at:null};}
