 function renderAudience(){const root=el('audience-editor'),editable=canWrite()&&!audience?.archived&&!heldProduct(audience?.definition?.rule);root.className='card mt-3';root.innerHTML='<div class="card-header"><h2 class="card-title">'+(audience?'Público · v'+audience.version:'Novo público')+'</h2><button type="button" class="btn btn-sm btn-outline-secondary ms-auto" data-crm-close>Fechar</button></div><form class="card-body"><div id="audience-edit-status" class="alert alert-info">'+(editable?(audience?'Edite as regras, confira a contagem e salve. As versões anteriores ficam no histórico.':'Escolha critérios confirmados pela fonte. Conte antes de salvar.'):'Consulta das regras salvas. Este público ou acesso não permite edição.')+'</div>'+input('Nome do público','audience-edit-name',audience?.name)+'<div id="audience-rule-root" class="mt-3"></div><div class="d-flex gap-2 flex-wrap mt-3"><button class="btn btn-outline-primary" type="button" data-crm-count data-crm-soon="audienceCount">Contar agora</button><button class="btn btn-primary" type="submit" data-crm-save>'+(audience&&release.audienceUpdates?'Salvar alterações':audience?'Salvar cópia':'Salvar público')+'</button><button class="btn btn-outline-secondary" type="button" data-crm-discard>Descartar alterações locais</button></div><div id="audience-edit-count" class="source-line mt-3">Contagem ainda não consultada.</div></form>'+(audience?'<div class="card-footer"><button type="button" class="btn btn-outline-secondary" data-crm-archive data-crm-soon="audienceUpdates"'+(!release.audienceUpdates||!canWrite()?' disabled aria-disabled="true"':'')+'>'+(audience.archived?'Restaurar público':'Arquivar público')+'</button><span class="source-line ms-2">Histórico preservado.</span></div>':'');
  let rule=audience?.definition?.rule||{op:'in_list',list_id:catalog.lists.find(l=>l.available)?.id||0};if(!['and','or'].includes(rule.op))rule={op:'and',rules:[rule]};el('audience-rule-root').append(ruleNode(rule));const form=root.querySelector('form');if(!editable)buttons(form,true);form.addEventListener('input',()=>{changed();el('audience-edit-count').textContent='Regras alteradas. Consulte uma nova contagem.';});root.querySelector('[data-crm-close]').addEventListener('click',()=>{if(dirty||busy||pending){notice('audience-edit-status','Salve ou descarte as alterações locais antes de fechar.','warning');return;}root.className='d-none';});form.querySelector('[data-crm-discard]').addEventListener('click',()=>{if(busy||pending)return;dirty=false;renderAudience();});
  form.querySelector('[data-crm-count]').addEventListener('click',async()=>{if(!release.audienceCount||!editable||busy)return;busy=true;try{const sentRevision=revision,definition=audienceInput();buttons(form,true);const result=await call('segments',{acao:'segmento_contar',brand:scope.brand,definition,expected_catalog_hash:catalog.catalog_hash},'POST');if(revision!==sentRevision){el('audience-edit-count').textContent='Regras alteradas. Consulte uma nova contagem.';return;}if(result.definition?.brand!==scope.brand||result.segment_id!==null||result.version!==null||typeof result.definition_hash!=='string'||!/^[a-f0-9]{64}$/.test(result.definition_hash)||typeof result.source_confirmed!=='boolean'||result.source_confirmed&&(!Number.isSafeInteger(result.eligible_count)||result.eligible_count<0))throw Error('COUNT_CONTRACT');el('audience-edit-count').textContent=result.source_confirmed?number(result.eligible_count)+' destinatários elegíveis · consulta '+when(result.checked_at):'A fonte não confirmou uma contagem. O valor permanece desconhecido.';}catch(e){el('audience-edit-count').textContent=explain(e);}finally{busy=false;buttons(form,!editable);refreshTestButtons();}});
  form.addEventListener('submit',event=>{event.preventDefault();if(!editable||pending)return;let definition;try{definition=audienceInput();}catch(e){notice('audience-edit-status',explain(e),'warning');return;}submit('segments',{acao:audience&&release.audienceUpdates?'segmento_salvar':'segmento_criar',brand:scope.brand,...(audience&&release.audienceUpdates?{id:audience.id,expected_version:audience.version}:{}),definition,expected_catalog_hash:catalog.catalog_hash},'audience');});
  holdButtons(root);updateAudienceLimits();el('audience-edit-name').setAttribute('maxlength','160');root.querySelector('[data-crm-archive]')?.addEventListener('click',()=>{if(!release.audienceUpdates||!canWrite()||dirty||busy||pending||!audience)return;submit('segments',audience.archived?{acao:'segmento_salvar',brand:scope.brand,id:audience.id,expected_version:audience.version,definition:audience.definition,expected_catalog_hash:catalog.catalog_hash}:{acao:'segmento_arquivar',brand:scope.brand,id:audience.id,expected_version:audience.version},'audience');});
 }
 async function load(view,ticket){nativeEligibleAccount=false;nativeCapabilityPending=null;nativeCapability=nativeReview=nativeFrozen=nativeCreateKey=null;dirty=false;campaign=audience=null;capability=catalog=testCapability=testPreview=null;records=[];const brand=s().brand,auth=await session();if(ticket!==s().ticket||brand!==s().brand)return;scope={ticket,brand,userId:auth.user.id};pending=stored();testAttempt=null;pendingNotice();for(const id of ['campaign-editor','audience-editor']){el(id).className='d-none';el(id).replaceChildren();}
  const route=view==='campaigns'?'campaigns':'segments';try{const cap=await call(route,{acao:view==='campaigns'?'campanha_capacidade':'segmento_capacidade',brand:scope.brand});if(ticket!==s().ticket)return;if(cap.brand!==scope.brand||cap.send!==false)throw Error('CONTRACT');capability=cap;
   if(view==='campaigns'){if(cap.read!==true)throw Object.assign(Error('SOURCE_UNAVAILABLE'),{code:cap.reason});try{testCapability=await call(route,{acao:'campanha_teste_capacidade',brand:scope.brand});}catch{testCapability=null;}nativeEligibleAccount=['felipebandeira+codex@oaristocrata.com','felipebandeira@oaristocrata.com'].includes(auth.user.email?.toLowerCase());const catalogue=await call(route,{acao:'campanha_catalogo',brand:scope.brand});const listing=await call(route,{acao:'campanha_listar',brand:scope.brand});if(ticket!==s().ticket)return;catalog=catalogue;records=listing.campaigns;if(!Array.isArray(records)||records.some(c=>c.definition?.brand!==scope.brand))throw Error('SCOPE');renderDraftList();notice('campaign-draft-status',cap.draft?'Crie e salve rascunhos da marca.':'Consulta disponível; este acesso não edita.');el('new-campaign').disabled=!canWrite();if(s().campaignId&&records.some(c=>c.id===s().campaignId)&&!pending)await openCampaign(s().campaignId);}
   else{catalog=s().audiences?.catalog;if(!catalog||catalog.brand!==scope.brand)throw Error('CATALOG');notice('audience-draft-status',cap.draft?'Crie, edite e arquive públicos. As versões anteriores ficam preservadas.':'Consulta disponível; a edição aguarda acesso ou fonte atual.');el('new-audience').disabled=!canWrite();}
  }catch(e){if(ticket!==s().ticket)return;notice(view==='campaigns'?'campaign-draft-status':'audience-draft-status',explain(e),'warning');el(view==='campaigns'?'new-campaign':'new-audience').disabled=true;}
 }
 el('new-campaign').addEventListener('click',()=>{if(canWrite()&&!dirty&&!busy&&catalog){campaign=null;campaignSelected(null);renderCampaign();}});el('new-audience').addEventListener('click',()=>{if(canWrite()&&!dirty&&!busy&&catalog){audience=null;renderAudience();}});
 return Object.freeze({load,openCampaign:id=>{if(!catalog||dirty||busy||pending||!records.some(c=>c.id===id))return;return openCampaign(id);},hasUnsaved:()=>dirty||busy,warnUnsaved:()=>{if(dirty||busy)notice(s().view==='campaigns'?'campaign-edit-status':'audience-edit-status','Salve ou descarte as alterações locais antes de mudar a tela ou a marca.','warning');},openAudience:record=>{if(!catalog||dirty||busy||pending)return;audience=record;renderAudience();},clear:()=>{if(dirty||busy)return;capability=catalog=null;for(const id of ['campaign-editor','audience-editor','campaign-drafts']){el(id).className='d-none';el(id).replaceChildren();}}});
